// Build the WhatsApp template payload + the SQL to mark the reminder sent
// (Spec 4.3 / 6.2). Business-initiated messages outside the 24h session window
// must use a pre-approved template (see whatsapp/templates/appointment_reminder.json).
return $input.all().map((item) => {
  const a = item.json;
  const when = new Date(a.scheduled_at).toLocaleString('en-GB', { timeZone: a.timezone || 'UTC', weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });
  const template = {
    messaging_product: 'whatsapp',
    to: a.whatsapp_number,
    type: 'template',
    template: {
      name: 'appointment_reminder',
      language: { code: 'en' },
      components: [
        { type: 'body', parameters: [ { type: 'text', text: a.clinic_name }, { type: 'text', text: when } ] },
        { type: 'button', sub_type: 'quick_reply', index: '0', parameters: [ { type: 'payload', payload: 'CONFIRM_' + a.id } ] },
        { type: 'button', sub_type: 'quick_reply', index: '1', parameters: [ { type: 'payload', payload: 'RESCHEDULE_' + a.id } ] }
      ]
    }
  };
  const col = a.which === '24h' ? 'reminder_24h_sent' : 'reminder_2h_sent';
  const markSql = `update appointments set ${col} = true where id = '${a.id}';`;
  return { json: { phone_number_id: a.phone_number_id, template, markSql, appointment_id: a.id, which: a.which } };
});
